INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(24545, 'koKR', 'Gdy płomień pożera przedmioty, ogarnia cię głębokie poczucie grozy.', 0),
(24547, 'koKR', '<Najwyższy lord Mograine przez chwilę przygląda ci się w milczeniu.>$b$bZdaje się, że ten etap próby $gzniosłeś:zniosłaś; godnie podziwu, $N.$b$bMódl się, by los nadal ci sprzyjał...', 0),
(24548, 'koKR', 'To powinno wystarczyć, $N.$b$bPrzyjdź do mnie, gdy Ostrze Cienia zostanie w pełni wzmocnione, a spróbuję je ukończyć.', 0),
(24549, 'koKR', 'Gratulacje, $N.$b$bWbrew przytłaczającym przeciwnościom $gprzetrwałeś:przetrwałaś; burzę.$b$bUfam, że nagroda okaże się współmierna do twojej determinacji...', 0),
(24743, 'koKR', 'Słuchaj uważnie, $N. Przyjmując tę broń, przypieczętowujesz swój los.$B$BZwyciężysz albo ulegniesz.$B$BTo ja postawiłem cię na tej ścieżce. Dlatego odpowiadam za ciebie osobiście. Jeśli się zachwiejesz, moim obowiązkiem będzie uwolnić cię od tego życia.$B$BZapamiętaj moje słowa, $N, i nie zawiedź.', 0),
(24748, 'koKR', 'A więc w końcu się dokonało.$b$bNiech mieszkańcy Azeroth na zawsze pamiętają, czego tu dokonaliśmy. Niech ofiara tak wielu płonie w ich sercach po wieczność. Niech nigdy nie wahają się narażać życia w obliczu wielkiego zła.', 0),
(24749, 'koKR', 'Dobra robota, $N.$b$bUkończenie naszego dzieła jest blisko.', 0),
(24756, 'koKR', 'Dobra robota, $N.$b$bCieniożal jest niemal na wyciągnięcie ręki.', 0),
(24757, 'koKR', 'Topór napił się do syta, $N, a kuźnia jest niemal gotowa do stworzenia Cieniożala...', 0),
(24815, 'koKR', 'By odpokutować grzechy, których dopuściłem się jako jeden z rycerzy śmierci Króla Lisza, poświęciłem się tworzeniu pierścieni wielkiej mocy, by nasi bracia i siostry mogli ich używać w tej walce.$B$B$GDowiodłeś:Dowiodłaś;, że jesteś $gcennym sojusznikiem:cenną sojuszniczką; w walce z Plagą, $N. Jeśli twoje oddanie nie osłabnie, mogę ulepszać pierwotny projekt pierścienia.$B$BWybieraj ścieżkę rozważnie. Zmiana zdania będzie kosztować.', 0),
(24819, 'koKR', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24820, 'koKR', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24821, 'koKR', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24822, 'koKR', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24823, 'koKR', 'Wciąż udowadniasz swoją wartość, $N. Przyjmij to nie jako dar, lecz jako narzędzie do walki z Plagą.', 0),
(24825, 'koKR', 'Wciąż udowadniasz swoją wartość, $N. Przyjmij to nie jako dar, lecz jako narzędzie do walki z Plagą.', 0),
(24826, 'koKR', 'Wciąż udowadniasz swoją wartość, $N. Przyjmij to nie jako dar, lecz jako narzędzie do walki z Plagą.', 0),
(24827, 'koKR', 'Wciąż udowadniasz swoją wartość, $N. Przyjmij to nie jako dar, lecz jako narzędzie do walki z Plagą.', 0),
(24828, 'koKR', 'Wciąż udowadniasz swoją wartość, $N. Przyjmij to nie jako dar, lecz jako narzędzie do walki z Plagą.', 0),
(24829, 'koKR', 'Jesteś $gprawdziwym orędownikiem:prawdziwą orędowniczką; naszej sprawy, $N. Nikt nie może twierdzić, że jest bardziej oddany tej walce niż ty.$B$BWróg wymawia twoje imię tylko szeptem, bo wie, że trzeba się z tobą liczyć.$B$BPrzyjmij ten skromny dar w nagrodę za twoje liczne triumfy.', 0),
(24830, 'koKR', 'Wciąż udowadniasz swoją wartość, $N. Przyjmij to nie jako dar, lecz jako narzędzie do walki z Plagą.', 0),
(24831, 'koKR', 'Jesteś $gprawdziwym orędownikiem:prawdziwą orędowniczką; naszej sprawy, $N. Nikt nie może twierdzić, że jest bardziej oddany tej walce niż ty.$B$BJesteś ostoją mądrości, a nasi sojusznicy mówią o tobie z najwyższą czcią. Wielu z nich zawdzięcza ci życie.$B$BPrzyjmij ten skromny dar w nagrodę za twoje liczne triumfy.', 0),
(24832, 'koKR', 'Wciąż udowadniasz swoją wartość, $N. Przyjmij to nie jako dar, lecz jako narzędzie do walki z Plagą.', 0),
(24833, 'koKR', 'Jesteś $gprawdziwym orędownikiem:prawdziwą orędowniczką; naszej sprawy, $N. Nikt nie może twierdzić, że jest bardziej oddany tej walce niż ty.$B$BPodobno sługi Plagi boją się ciebie bardziej niż samego Króla Lisza. Jesteś wcieloną pomstą.$B$BPrzyjmij ten skromny dar w nagrodę za twoje liczne triumfy.', 0),
(24834, 'koKR', 'Wciąż udowadniasz swoją wartość, $N. Przyjmij to nie jako dar, lecz jako narzędzie do walki z Plagą.', 0),
(24835, 'koKR', 'Jesteś $gprawdziwym orędownikiem:prawdziwą orędowniczką; naszej sprawy, $N. Nikt nie może twierdzić, że jest bardziej oddany tej walce niż ty.$B$BJesteś natchnieniem dla naszych sojuszników, a twoje niezachwiane męstwo każe się zawahać nawet najbardziej doświadczonym generałom wroga.$B$BPrzyjmij ten skromny dar w nagrodę za twoje liczne triumfy.', 0),
(24836, 'koKR', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24837, 'koKR', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24838, 'koKR', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24839, 'koKR', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24840, 'koKR', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24841, 'koKR', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24842, 'koKR', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24843, 'koKR', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24844, 'koKR', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24845, 'koKR', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24846, 'koKR', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24847, 'koKR', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(24869, 'koKR', 'Dziękuję, $N!$B$BMam wobec ciebie dług wdzięczności za uratowanie przyjaciela, którego uważałem za straconego na zawsze w szponach Kultu. A Krucjata Argentu ma u ciebie dług za bezcenne informacje, które Darnavan przynosi z czasów, gdy przemierzał korytarze tej cytadeli jako jeden z kultystów.$B$BProszę, przyjmij to w dowód wdzięczności. Niech Światłość doda ci sił, gdy będziesz torować sobie drogę przez to straszne miejsce.', 0),
(24870, 'koKR', 'Olbrzym nie żyje? Za Hordę!$B$BDroga naprzód i w górę stoi otworem. Weź trochę tych łupów wojennych w dowód naszej wdzięczności, a gdy Mroźny Tron zostanie starty w pył, wypijemy razem za zwycięstwo!', 0),
(24873, 'koKR', 'Nareszcie mamy żywe okazy do badań! $GPomogłeś:Pomogłaś; dziś ocalić niezliczone istnienia, $N.$B$BProszę, przyjmij to w podziękowaniu za ten wielki czyn.', 0),
(24874, 'koKR', 'Uff, myślałem, że już po mnie! Słyszałem, że w tych salach odprawiany jest jakiś rytuał wskrzeszenia, i poszedłem przyjrzeć się z bliska, ale jeden z tych przeklętych wampirów mnie wywęszył. Powiesili mnie tutaj i wysysali ze mnie energię życiową w nadziei, że się złamię i wyjawię nasze plany ataku. Jakbym w ogóle wiedział, co planuje Tirion!$b$bProszę, przyjmij te łupy wojenne jako drobny dowód wdzięczności za uratowanie mi życia.', 0),
(24875, 'koKR', 'Dziękuję, $N!$B$BMam wobec ciebie dług wdzięczności za uratowanie przyjaciela, którego uważałem za straconego na zawsze w szponach Kultu. A Krucjata Argentu ma u ciebie dług za bezcenne informacje, które Darnavan przynosi z czasów, gdy przemierzał korytarze tej cytadeli jako jeden z kultystów.$B$BProszę, przyjmij to w dowód wdzięczności. Niech Światłość doda ci sił, gdy będziesz torować sobie drogę przez to straszne miejsce.', 0),
(24877, 'koKR', 'Olbrzym nie żyje? Za Hordę!$B$BDroga naprzód i w górę stoi otworem. Weź trochę tych łupów wojennych w dowód naszej wdzięczności, a gdy Mroźny Tron zostanie starty w pył, wypijemy razem za zwycięstwo!', 0),
(24878, 'koKR', 'Nareszcie mamy żywe okazy do badań! $GPomogłeś:Pomogłaś; dziś ocalić niezliczone istnienia, $N.$B$BProszę, przyjmij to w podziękowaniu za ten wielki czyn.', 0),
(24879, 'koKR', 'Uff, myślałem, że już po mnie! Słyszałem, że w tych salach odprawiany jest jakiś rytuał wskrzeszenia, i poszedłem przyjrzeć się z bliska, ale jeden z tych przeklętych wampirów mnie wywęszył. Powiesili mnie tutaj i wysysali ze mnie energię życiową w nadziei, że się złamię i wyjawię nasze plany ataku. Jakbym w ogóle wiedział, co planuje Tirion!$b$bProszę, przyjmij te łupy wojenne jako drobny dowód wdzięczności za uratowanie mi życia.', 0),
(24912, 'koKR', 'Odsuń się, $N, i przygotuj się.', 0),
(24914, 'koKR', '<Gdy Mograine kreśli na każdej ścianie skrzyni złożony wzór run, pojawia się zarys wieka, a po komnacie niesie się echem ciche kliknięcie.>$B$BProszę bardzo, $N.', 0),
(24915, 'koKR', 'Niemożliwe...$B$BOjcze, czy to ty?!$B$B$GOddałeś:Oddałaś; mi wielką przysługę, $gbohaterze:bohaterko;. Oddaję ci wodze mojego wiernego rumaka. Zrób z nim, co zechcesz, ale nie zapominaj o tych, którzy pomogli ci w tym wiekopomnym czynie.', 0),
(25239, 'koKR', 'Wciąż udowadniasz swoją wartość, $N. Przyjmij to nie jako dar, lecz jako narzędzie do walki z Plagą.', 0),
(25240, 'koKR', 'Wciąż udowadniasz swoją wartość, $N. Przyjmij to nie jako dar, lecz jako narzędzie do walki z Plagą.', 0),
(25242, 'koKR', 'Jesteś $gprawdziwym orędownikiem:prawdziwą orędowniczką; naszej sprawy, $N. Nikt nie może twierdzić, że jest bardziej oddany tej walce niż ty.$B$BPodobno sługi Plagi boją się ciebie bardziej niż samego Króla Lisza. Jesteś wcieloną potęgą.$B$BPrzyjmij ten skromny dar w nagrodę za twoje liczne triumfy.', 0),
(25246, 'koKR', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
(25247, 'koKR', 'Obyś $gznalazł:znalazła; to, czego szukasz, $gbracie:siostro;.', 0),
