INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(36626, 2, 0, 'koKR', '%s puszcza bąka.'),
(36626, 6, 0, 'koKR', '%s wymiotuje.'),
(36789, 4, 0, 'koKR', 'Wybaczcie mi to, co czynię! Nie... mogę... przestać... ZOSTAŁY TYLKO KOSZMARY!'),
(36789, 5, 0, 'koKR', 'Tragiczna strata...'),
(36789, 6, 0, 'koKR', 'NIEUDACZNICY!'),
(37129, 8, 0, 'koKR', 'Sama pomsta... nie wystarczyła!'),
(37187, 7, 0, 'koKR', 'Najwyższy nadrządca Zaurzykieł podchodzi do syna i klęka przy jego ciele.'),
(37187, 8, 0, 'koKR', 'No\'ku kil zil\'nok ha tar.'),
(37187, 9, 0, 'koKR', 'Najwyższy nadrządca Zaurzykieł podnosi ciało syna i rusza w stronę Variana'),
(37813, 3, 0, 'koKR', '%s unieruchamia Muradina i jego strażników.'),
(37970, 6, 0, 'koKR', '...dlaczego...?'),
(37973, 6, 0, 'koKR', '%s charczy i umiera.');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(13022, 'koKR', '%s zanosi się obłąkańczym rechotem.\n', '', 0),
(32731, 'koKR', 'Wiem, co by zrobił.', '', 0),
(32732, 'koKR', 'Powiedziałby ci: Thrall. Prowadź swój lud.', '', 0),
(32733, 'koKR', 'Wracajmy do domu, stary przyjacielu.', '', 0),
(36706, 'koKR', '%s uwalnia zarodniki gazowe!', '', 0),
(36707, 'koKR', '%s zaczyna rzucać |cFFFF7F00Cuchnącą zarazę!|r', '', 0),
(36923, 'koKR', 'To nasz ostatni bój. To, co się tu wydarzy, będzie rozbrzmiewać przez wieki. Bez względu na wynik wszyscy będą wiedzieć, że walczyliśmy z honorem. Że walczyliśmy o wolność i bezpieczeństwo naszego ludu.$B$BPamiętaj, $gbohaterze:bohaterko;, strach jest twoim największym wrogiem w tych splugawionych salach. Zahartuj serce, a twoja dusza zalśni jaśniej niż tysiąc słońc. Wróg zachwieje się na twój widok. Padnie, gdy ogarnie go światło sprawiedliwości!', '', 0),
(36945, 'koKR', 'Przygotujcie broń, bracia z Argentu. Wrykule będą bronić Mroźnej Królowej za cenę życia.', '', 0),
(36946, 'koKR', 'Dość czczej gadaniny! Przybyli nasi czempioni – wspierajcie ich, gdy będziemy przebijać się przez salę!', '', 0),
(36948, 'koKR', 'Nawet śmierć tutaj jest lepsza niż kolejny dzień zbierania odczynników dla tego szaleńca Finklesteina.', '', 0),
(37013, 'koKR', 'Ściągnijcie ich do nas, a pomożemy wam.', '', 0),
(37015, 'koKR', 'Szybko, naprzód!', '', 0),
(37016, 'koKR', 'Jej posiłki zaraz nadejdą, musimy ją szybko powalić!', '', 0),
(37017, 'koKR', 'Ściągnę na siebie jej ataki. Odeślijcie naszych braci z powrotem do grobów, a potem pomóżcie mi ją powalić!', '', 0),
(37020, 'koKR', '', 'Głupi Croku. Przyprowadziłeś mi posiłki. Powstańcie, czempioni Argentu, i służcie Królowi Liszowi po śmierci!', 0),
(37024, 'koKR', '', 'Może kiedyś walczyłeś u mego boku, Croku, ale teraz jesteś tylko zdrajcą. Chodź, nadchodzi twoja druga śmierć!', 0),
(37027, 'koKR', 'To nasz ostatni bój. To, co się tu wydarzy, będzie rozbrzmiewać przez wieki. Bez względu na wynik wszyscy będą wiedzieć, że walczyliśmy z honorem. Że walczyliśmy o wolność i bezpieczeństwo naszego ludu!\n', '', 0),
(37028, 'koKR', 'Pamiętajcie, bohaterowie, strach jest waszym największym wrogiem w tych splugawionych salach. Zahartujcie serca, a wasze dusze zalśnią jaśniej niż tysiąc słońc. Wróg zachwieje się na wasz widok. Padnie, gdy ogarnie go światło sprawiedliwości!', '', 0),
(37029, 'koKR', 'Nasz marsz na Cytadelę Lodowej Korony rozpoczyna się teraz!', '', 0),
(37031, 'koKR', 'ARTHASIE! Przysiągłem, że zobaczę cię martwego, a Plagę rozbitą! Dokończę to, co zacząłem w Kaplicy Świetlistej Nadziei!', '', 0),
(37034, 'koKR', 'Złamanie tego tutaj kosztowało mnie wiele wysiłku. Okrucieństwa, jakich dopuściłem się wobec jego duszy... Opierał się tak długo, ale wkrótce pokłoni się swojemu królowi.', '', 0),
(37035, 'koKR', 'NIGDY! Ja... nigdy nie będę... ci... służył...', '', 0),
(37038, 'koKR', 'Na Światłość, tak musi się stać!', '', 0),
(37049, 'koKR', 'Dobre wieści, moi drodzy! Naprawiłem rury z trującym szlamem!', '', 0),
(37051, 'koKR', 'Paladyn wciąż żyje? Czy to możliwe, najwyższy lordzie? Czy mógł przeżyć?', '', 0),
(37053, 'koKR', 'Zatem musimy go uratować! Jeśli ocalimy Bolvara Fordragona, być może uśmierzymy niepokoje między Przymierzem a Hordą.', '', 0),
(37054, 'koKR', 'Nasza misja jest teraz jasna: Król Lisz odpowie za swoje zbrodnie, a my uratujemy najwyższego lorda Bolvara Fordragona!', '', 0),
(37055, 'koKR', 'Kor\'kronie, przygotować Młot Orgrima do ostatniego rejsu! Czempioni, nasza kanonierka znajdzie miejsce do zacumowania w górnych partiach cytadeli. Tam się spotkamy!', '', 0),
(37056, 'koKR', 'Moc Światłości nie zna granic, Zaurzykieł. Jego dusza jest poddana ogromnej próbie, ale on żyje – na razie.', '', 0),
(37063, 'koKR', 'Ja chyba zrobić złą kupkę. Zaraz zrobi bum!', '', 0),
(37064, 'koKR', '|TInterface\\Icons\\spell_shadow_unstableaffliction_2.blp:16|t%s zaczyna rzucać |cFFFF0000Wybuch niestabilnego szlamu!|r', '', 0),
(37065, 'koKR', '', 'Nędzne stworzenia! Gińcie!', 0),
(37074, 'koKR', 'Nigdy... nie mogłem sięgnąć... najwyższej półki...', '', 0),
(37075, 'koKR', 'TO za przyniesienie mi zepsutej pajęczej posoki!\n', '', 0),
(37076, 'koKR', 'Wy nędzni głupcy nigdy nie potrafiliście wybrać porządnego nietoperzowego skrzydła.', '', 0),
(37077, 'koKR', 'Nie... pozwólcie Finklesteinowi... przerobić mnie... na mikstury...', '', 0),
(37105, 'koKR', 'Nie wolno im zbliżyć się do Mroźnej Królowej. Szybko, zatrzymać ich!', 'Nie wolno im zbliżyć się do Mroźnej Królowej. Szybko, zatrzymać ich!', 0),
(37135, 'koKR', '', 'Może... miałeś rację, Croku.', 0),
(37163, 'koKR', '', 'Zginęli tak łatwo. Nieważne.', 0),
(37164, 'koKR', 'Ach! Muszę na chwilę odpocząć.\n', '', 0),
(37165, 'koKR', 'Czempioni! Nie mogę jej dłużej powstrzymywać.', '', 0),
(37179, 'koKR', 'Przygotuj się, $N.$b$bNadszedł czas, by panowanie Króla Lisza dobiegło końca.', '', 0),
(37180, 'koKR', 'Czym jest Popielny Werdykt?', 'Czym jest Popielny Werdykt?', 0),
(37181, 'koKR', 'Popielny Werdykt to wybrana grupa najzdolniejszych rzemieślników Hebanowego Miecza i Krucjaty Argentu. Jego powstanie symbolizuje jedność naszych sił w tym ostatecznym szturmie na Króla Lisza i jego sługi.$b$bTo dzięki staraniom Popielnego Werdyktu odkryliśmy, jak podporządkować sobie pierwotny saronit.', '', 0),
(37182, 'koKR', 'Jak mogę nauczyć się obrabiać pierwotny saronit?', 'Jak mogę nauczyć się obrabiać pierwotny saronit?', 0),
(37183, 'koKR', 'Porozmawiaj z alchemikiem Finklesteinem, $N. On wskaże ci drogę.$b$bOkaż lojalność, a poznasz ich metody.', '', 0),
(37195, 'koKR', 'Król Lisz jest blisko, $n. Jego głos ze mnie szydzi...$b$bUciszmy go wreszcie!', '', 0),
(37248, 'koKR', 'A więc się zaczęło...', '', 0),
(37249, 'koKR', 'Patrzcie! Połączenie świętego i splugawionego – wykucie Ostrza Cienia, broni o niewyobrażalnym potencjale!', '', 0),
(37250, 'koKR', 'Nagnij ją do swej woli, a będziesz $gwładał:władała; niewysłowioną mocą!', '', 0),
(37251, 'koKR', 'Zawiedź, a twoja dusza na zawsze stanie się jej niewolnicą.\n', '', 0),
(37443, 'koKR', 'Spokój sanktuarium pana został zakłócony!', '', 0),
(37458, 'koKR', 'Z każdym zabitym przez was żołnierzem Hordy, z każdym poległym psem Przymierza armie Króla Lisza rosły w siłę. Nawet teraz val\'kyrie pracują nad tym, by wskrzesić waszych poległych jako Plagę.\n', '', 0),
(37459, 'koKR', 'Zaraz zrobi się o wiele gorzej. Chodźcie, zakosztujcie mocy, którą obdarzył mnie Król Lisz!', '', 0),
(37471, 'koKR', 'Krasnoludy...', '', 0),
(37477, 'koKR', 'Jestem... wreszcie... wolny...', '', 0),
(37525, 'koKR', 'Za wami leży ciało mojego jedynego syna. Nic mnie od niego nie powstrzyma.', '', 0),
(37529, 'koKR', 'Nie zapomnę tej... życzliwości. Dziękuję, Wasza Wysokość', '', 0),
(37533, 'koKR', 'Wiele uczyniliście w tej wojnie z Plagą. Niech Światłość was otuli.', '', 0),
(37534, 'koKR', 'Utraty naszych towarzyszy nie dało się uniknąć. Żyli i umierali w służbie Krucjaty Argentu.', '', 0),
(37535, 'koKR', 'Co może odkupić to bezbożne miejsce? Dziękuję.', '', 0),
(37536, 'koKR', 'Strzeżcie się niebezpieczeństw, które czekają przed wami... i postarajcie się zostać w jednym kawałku.', '', 0),
(37630, 'koKR', '$GDzielny żołnierzu:Dzielna żołnierko; Hordy, salutuję ci! Z pewnością zniszczyłaby nas kanonierka Przymierza, gdyby nie ty i twoi sojusznicy.$B$BOdpocznij chwilę, zanim przypuścimy szturm na górne partie cytadeli.', '', 0),
(37631, 'koKR', 'Jesteśmy gotowi, najwyższy nadrządco. Król Lisz musi upaść!', 'Jesteśmy gotowi, najwyższy nadrządco. Król Lisz musi upaść!', 0),
(37633, 'koKR', 'Lok\'tar ogar! Jesteśmy gotowi! Naprzód, bracie orku!', 'Lok\'tar ogar! Jesteśmy gotowi! Naprzód, bracie orku!', 0),
(37634, 'koKR', 'Kor\'kronie, wymarsz! Czempioni, uważajcie na plecy. Plaga już...', '', 0),
(37635, 'koKR', 'Dołącz do mnie, ojcze. Dołącz do mnie, a zmiażdżymy ten świat w imię Plagi – ku chwale Króla Lisza!', '', 0),
(37638, 'koKR', 'Mój chłopiec zginął pod Bramą Gniewu. Jestem tu tylko po to, by zabrać jego ciało.', '', 0),
(37639, 'koKR', 'Uparty i stary. Jakie masz szanse? Jestem silniejszy i potężniejszy, niż ty kiedykolwiek byłeś.', '', 0),
(37640, 'koKR', 'Daliśmy mu na imię Dranosh – w języku orków znaczy to „Serce Draenoru”. Nie pozwoliłem czarnoksiężnikom go zabrać. Mój chłopiec miał być bezpieczny, ukryty przez starszyznę Garadaru.', '', 0),
(37641, 'koKR', 'Zanim jego matka umarła, obiecałem jej, że przejdę przez Mroczny Portal sam – czy przeżyję, czy zginę, mój syn będzie bezpieczny. Nieskażony...', '', 0),
(37642, 'koKR', 'Dziś dotrzymuję tej obietnicy.', '', 0),
(37644, 'koKR', 'Żałosny stary ork! Chodźcie więc, bohaterowie. Zmierzcie się z potęgą Plagi!', '', 0),
(37646, 'koKR', '%s kaszle.', '', 0),
(37647, 'koKR', '%s płacze nad zwłokami syna.', '', 0),
(37648, 'koKR', 'Doczekasz się należytej ceremonii w Nagrandzie, obok stosów twojej matki i przodków.\n', '', 0),
(37649, 'koKR', 'Honor, młodzi bohaterowie... bez względu na to, jak ciężka jest bitwa... nigdy się go nie wyrzekajcie.', '', 0),
(37653, 'koKR', '', 'Chodź, Zgubo Plagi. Pokażę panu, które z nas naprawdę zasługuje na tytuł „Czempiona”!', 0),
(37654, 'koKR', '', 'Co za żałosny wybór sojusznika, Croku!', 0),
(37658, 'koKR', 'Już nie boli, prawda?\n', '', 0),
(37659, 'koKR', 'Przykro mi...', '', 0),
(37660, 'koKR', 'Czujecie, jak pali?', '', 0),
(37661, 'koKR', 'Co... ja zrobiłem? Nie!', '', 0),
(37662, 'koKR', 'A więc tak to się kończy, gdy stoi się za blisko bomby!', '', 0),
(37663, 'koKR', 'Co za... wybuchowy finał!', '', 0),
(37664, 'koKR', 'Co? Ta siła...? Cały ból zniknął! Musicie... dołączyć do mnie w wiecznych objęciach śmierci!\n', '', 0),
(37665, 'koKR', 'Żadne leczenie już mnie nie uratuje. Walczcie dalej, bracia...', '', 0),
(37666, 'koKR', 'Proszę... spalcie moje szczątki. Niech w zaświatach będzie mi ciepło...', '', 0),
(37667, 'koKR', 'Nie! Czemu odmówiono mi śmierci w płomieniach? Wszyscy musicie SPŁONĄĆ!', '', 0),
(37668, 'koKR', 'To był... godny żywot po śmierci.', '', 0),
(37669, 'koKR', 'Przed wolą Króla Lisza nie ma ucieczki. Szykujcie się na wybuchowe spotkanie!', '', 0),
(37823, 'koKR', 'Zabawa?', '', 0),
(37824, 'koKR', 'Tatusiu, udało mi się!', '', 0),
(37825, 'koKR', 'Trup, trup, trup!', '', 0),
(37826, 'koKR', 'Ta... tusiu...', '', 0),
(37827, 'koKR', 'Koniec zabawy!', '', 0),
(37829, 'koKR', 'Ja nie czuć się dobrze...', '', 0),
(37830, 'koKR', 'Nie! Wy zabić Śmierdziela! Wy zapłacić!', '', 0),
(37831, 'koKR', 'JUHUUUUUU!', '', 0),
(37832, 'koKR', 'Ja to zepsuciłem...', '', 0),
(37833, 'koKR', 'Tatuś zrobi z was nowe zabawki!', '', 0),
(37834, 'koKR', 'Złe wieści, tatusiu...', '', 0),
(37835, 'koKR', 'CZAS SPAĆ!', '', 0),
(37836, 'koKR', 'Fuj, klejące!', '', 0),
(37837, 'koKR', 'Co? Skarbuś? Nieeeeeeeeee!!!', '', 0),
(37838, 'koKR', 'Dobre wieści, moi drodzy! Chyba udoskonaliłem zarazę, która zniszczy całe życie w Azeroth!', '', 0),
(37839, 'koKR', 'Hm, ciekawe...', '', 0),
(37841, 'koKR', 'Złe wieści, moi drodzy... Chyba z tego nie wyjdę...', '', 0),
(37843, 'koKR', 'Zwykła chmura gazu, ale uważajcie, bo to wcale nie jest zwykła chmura gazu!', '', 0),
(37844, 'koKR', 'Hm, nic nie czuję. Co?! Skąd one się wzięły?', '', 0),
(37845, 'koKR', 'Smakuje jak... wiśnia! OCH! Przepraszam!', '', 0),
(37846, 'koKR', 'Dwa szlamy, jeden pokój. Tyle cudownych możliwości!', '', 0),
(37847, 'koKR', 'Straszne wieści, moi drodzy. Zgnilec nie żyje, ale wspaniałe wieści, moi drodzy! Szlamu zostawił mi w bród, zrobię z niego istny cud! Co? Jestem poetą, a nawet o tym nie wiedziałem... Zdumiewające!', '', 0),
(37848, 'koKR', 'Och, Ropniaku, zawsze byłeś moim ulubieńcem – zaraz po Zgnilcu. Dobra wiadomość jest taka, że zostawiłeś po sobie mnóstwo gazu. Niemal czuję jego smak!', '', 0),
(37849, 'koKR', '%s wydaje z siebie głośne, przeciągłe wycie!', '%s wydaje z siebie głośne, przeciągłe wycie!', 0),
(37852, 'koKR', 'MOJE SIŁY POWRÓCIŁY! Niech Ysera obdarzy mnie łaską, bym mogła posłać te plugawe stwory na wieczny spoczynek!', '', 0),
(37855, 'koKR', 'Proszę, przekuj dla mnie Ostrze Cienia, najwyższy lordzie Mograine.', 'Proszę, przekuj dla mnie Ostrze Cienia, najwyższy lordzie Mograine.', 0),
(37872, 'koKR', '|TInterface\\Icons\\ability_creature_disease_02.blp:16|tDotknęła cię |cFF00FF00Zmutowana infekcja!|r', '', 0),
(37875, 'koKR', 'Bohaterowie, pomóżcie mi. Nie... nie zdołam ich dłużej powstrzymywać. Musicie uleczyć moje rany!', '', 0),
(37876, 'koKR', 'Oto portal do Snu. Wasze ocalenie kryje się w nim, bohaterowie...', '', 0),
(37878, 'koKR', 'Wracają mi siły. Naprzód, bohaterowie!', '', 0),
(37899, 'koKR', 'Weź je, $gśmiertelniku:śmiertelniczko;, te dusze i tak wkrótce znów będą moje.', '', 0),
(37900, 'koKR', 'Wkrótce, $gśmiertelniku:śmiertelniczko;, i ty będziesz mieć ostrze za więzienie.', '', 0),
(37901, 'koKR', 'Pamiętaj, $gbohaterze:bohaterko;: ja też kiedyś szukałem broni o wielkiej mocy...', '', 0),
(37902, 'koKR', 'Widzę, że i ty zbierasz dusze dla własnych celów. Czy naprawdę tak bardzo się różnimy, $gczempionie:czempionko;?', '', 0),
(37903, 'koKR', 'Tak, zrób to! Stwórz swoją nową, potworną broń. Ona także będzie mi służyć, gdy twoja dusza stanie się moja.', '', 0),
(37904, 'koKR', 'Przynieś mi swoją broń, $gczempionie:czempionko;, abym mógł nakarmić ją duszą jej właściciela!', '', 0),
(37905, 'koKR', 'Spójrz na siebie, dziecko – $gniedoszły władco:niedoszła władczyni; dusz... nie pojmujesz potęgi, którą mam na swoje rozkazy!', '', 0),
(37906, 'koKR', 'Chodź do mnie, $guzurpatorze:uzurpatorko;! Nakarm MOJE ostrze!', '', 0),
(37907, 'koKR', 'Moje próby cię wzmocniły, $gczempionie:czempionko;. Dobrze mi posłużysz!', '', 0),
(37908, 'koKR', 'Nigdy nie musiałem żałować, że cię oszczędziłem, $gśmiertelniku:śmiertelniczko;. Zawsze znajdujesz sposób, by mnie rozbawić.', '', 0),
(37909, 'koKR', 'Ta chwila jest już blisko, $gśmiertelniku:śmiertelniczko;. Przez wieczność będziesz harować w nowym Azeroth!', '', 0),
(37910, 'koKR', 'Więcej dusz... tak, więcej... trudno ci będzie przestać, $gśmiertelniku:śmiertelniczko;.', '', 0),
(37911, 'koKR', 'Głód, który czuje twoja broń, to tylko cień tego, co cię czeka. Chcesz zobaczyć prawdziwy głód? Prawdziwą moc? Idź dalej, $gbohaterze:bohaterko;. Czekam.', '', 0),
(37912, 'koKR', 'Błądzicie po omacku w ciemności. Nie ma tu światła. Nie ma litości! Lodowa Korona pochłonęła dusze lepszych bohaterów niż wy.', '', 0),
(37913, 'koKR', 'Twoje serce – jego nieustanne bicie budzi we mnie wstręt. Uciszę je, tak jak uciszyłem własne.', '', 0),
(37914, 'koKR', 'Światłość cię opuści, $gbohaterze:bohaterko;, tak jak opuściła mnie.', '', 0),
(37977, 'koKR', '%s nadziewa na włócznię: $n!', '%s nadziewa na włócznię: $n!', 0),
(37978, 'koKR', '$n roztrzaskuje Tarczę eteru – %s traci osłonę!', '$n roztrzaskuje Tarczę eteru – %s traci osłonę!', 0),
(37991, 'koKR', 'Jesteście niczym!', '', 0),
(37992, 'koKR', 'Twoja dusza nie znajdzie tu odkupienia!', '', 0),
(37994, 'koKR', 'Stałem się... ŚMIERCIĄ!', '', 0),
(37995, 'koKR', 'Ziemia spływa waszą krwią!', '', 0),
(37997, 'koKR', '', 'Głupi śmiertelnicy. Myśleliście, że tak łatwo nas pokonacie? San\'layn to nieśmiertelni żołnierze Króla Lisza! Teraz zmierzycie się z ich połączoną potęgą!', 0),
(37998, 'koKR', 'Kolacja... podana.', '', 0),
(37999, 'koKR', 'Czy TERAZ widzicie potęgę Mrocznoupadłych?', '', 0),
(38000, 'koKR', 'POKŁOŃCIE SIĘ SAN\'LAYN!', '', 0),
(38001, 'koKR', 'Naxxanar był tylko chwilowym niepowodzeniem! Dzięki mocy kuli Valanar dokona zemsty!', '', 0),
(38002, 'koKR', 'Mój kielich się przelewa.', '', 0),
(38003, 'koKR', 'Czy kiedykolwiek byliście zagrożeniem?', '', 0),
(38004, 'koKR', 'Prawdę odnajduje się w śmierci.', '', 0),
(38005, 'koKR', 'Moja królowo, oni... nadchodzą.', '', 0),
(38006, 'koKR', 'Cóż za cudowna moc! Kula Mrocznoupadłych uczyniła mnie NIEZWYCIĘŻONYM!', '', 0),
(38007, 'koKR', 'Krew popłynie.', '', 0),
(38008, 'koKR', 'Pokarm dla robaków.', '', 0),
(38009, 'koKR', 'Błagajcie o litość!', '', 0),
(38010, 'koKR', 'Drżyjcie przed Taldaramem, śmiertelnicy, bo płynie przeze mnie moc kuli!', '', 0),
(38011, 'koKR', 'Rozkoszujcie się bólem!', '', 0),
(38038, 'koKR', 'Nadzieja gaśnie...', '', 0),
(38040, 'koKR', 'Nadszedł koniec!', '', 0),
(38041, 'koKR', 'Stańcie teraz w obliczu swego tragicznego końca.', '', 0),
(38042, 'koKR', 'Ostrze Mrozu łaknie...', '', 0),
(38043, 'koKR', 'Ostrze Mrozu, BĄDŹ MI POSŁUSZNE!', '', 0),
(38044, 'koKR', 'Ostrze Mrozu pożywia się duszą waszego poległego sojusznika!', '', 0),
(38046, 'koKR', 'Zamrożę was od środka, aż zostanie z was tylko lodowa skorupa.', '', 0),
(38047, 'koKR', 'Patrzcie, jak świat wokół was się wali!', '', 0),
(38048, 'koKR', '', 'Podjęliście... niemądrą... decyzję.', 0),
(38052, 'koKR', 'Val\'kyrie, wasz pan wzywa!', '', 0),
(38053, 'koKR', '', 'Tylko łyczek...', 0),
(38054, 'koKR', 'Stoisz teraz na uświęconej ziemi Plagi. Światłość cię tu nie ochroni, paladynie. Nic cię nie ochroni...', '', 0),
(38055, 'koKR', 'Mogłeś być moim największym czempionem, Fordringu: siłą ciemności, która zaleje ten świat i wprowadzi go w nową erę niezgody.', '', 0),
(38056, 'koKR', 'Lecz ten zaszczyt już ci się nie należy. Wkrótce będę miał nowego czempiona.', '', 0),
(38058, 'koKR', '', 'Poznajcie mój głód!', 0),
(38059, 'koKR', 'Koniec końców wszyscy będziecie mi służyć.', '', 0),
(38061, 'koKR', '', 'CIERPCIE!', 0),
(38062, 'koKR', '', 'Poradzicie sobie z tym?', 0),
(38063, 'koKR', '', 'Nadchodzi...', 0),
(38064, 'koKR', '', 'Jakże... niefortunnie.', 0),
(38065, 'koKR', '', 'Tak! Pij, mój skarbie! Teraz należysz do mnie!', 0),
(38066, 'koKR', '', 'Naprawdę...? To wszystko, na co was stać?', 0),
(38067, 'koKR', '', 'Jaka szkoda.', 0),
(38068, 'koKR', '', 'To się kończy TERAZ!', 0),
(38069, 'koKR', '', 'Ale... tak dobrze... nam się... układało...', 0),
(38070, 'koKR', 'A więc wychwalana sprawiedliwość Światłości wreszcie nadeszła? Mam odłożyć Ostrze Mrozu i zdać się na twoją łaskę, Fordringu?', '', 0),
(38071, 'koKR', 'Przekonasz się o tym na własnej skórze. Gdy moje dzieło dobiegnie końca, będziesz błagał o litość – a ja ci jej odmówię. Twoje pełne udręki krzyki będą świadectwem mojej nieokiełznanej mocy...', '', 0),
(38072, 'koKR', 'Utrzymam cię przy życiu, byś był świadkiem końca, Fordringu. Nie chciałbym, by największy czempion Światłości przegapił chwilę, gdy ten nędzny świat zostanie przekształcony na moje podobieństwo.', '', 0),
(38073, 'koKR', 'Chodźcie więc, czempioni. Nakarmcie mnie swoim gniewem!', '', 0),
(38074, 'koKR', 'Nie ma już pytań bez odpowiedzi. Nie ma wątpliwości. JESTEŚCIE największymi czempionami Azeroth. Pokonaliście każde wyzwanie, jakie przed wami postawiłem. Moi najpotężniejsi słudzy padli przed waszym nieustępliwym naporem... waszą nieokiełznaną furią...', '', 0),
(38075, 'koKR', 'Czy to naprawdę prawość wami kieruje? Zastanawiam się...', '', 0),
(38076, 'koKR', 'Dobrze ich wyszkoliłeś, Fordringu. Przyprowadziłeś największą siłę bojową, jaką znał ten świat... prosto w moje ręce – dokładnie tak, jak zamierzałem! Zostaniesz nagrodzony za swoje nieświadome poświęcenie.', '', 0),
(38077, 'koKR', 'Patrz, jak wskrzeszam ich z martwych, by stali się panami Plagi. Spowiją ten świat chaosem i zniszczeniem. Upadek Azeroth nastąpi z ich rąk – a ty zginiesz pierwszy.', '', 0),
(38078, 'koKR', 'Cóż za rozkoszna ironia.', '', 0),
(38079, 'koKR', '', 'Powstańcie, bracia, i zniszczcie naszych wrogów!', 0),
(38080, 'koKR', 'Niemożliwe...', '', 0),
(38120, 'koKR', 'Wspaniałe wieści, moi drodzy! Szlam znów płynie!', '', 0),
(38121, 'koKR', '%s: Bariera many migocze i znika!', '', 0),
(38122, 'koKR', 'Cóż to za zamieszanie? Śmiecie wkraczać na tę uświęconą ziemię? To miejsce stanie się waszym ostatnim spoczynkiem!', '', 0),
(38123, 'koKR', 'Czy pojmujecie już daremność swoich czynów?', '', 0),
(38124, 'koKR', 'Przyjmijcie ciemność... wieczną ciemność.', '', 0),
(38125, 'koKR', 'Wszystko to część planu Pana... Wasz koniec jest nieunikniony...', '', 0),
(38126, 'koKR', 'Dość! Widzę, że muszę wziąć sprawy w swoje ręce!', '', 0),
(38127, 'koKR', 'Jesteście słabi, bezsilni wobec mojej woli!', '', 0),
(38128, 'koKR', 'Ta szarada trwa już wystarczająco długo!', '', 0),
(38130, 'koKR', 'Przyjmij to błogosławieństwo i pokaż tym intruzom przedsmak mocy Pana!', '', 0),
(38132, 'koKR', 'Uwalniam cię od Klątwy Ciała!', '', 0),
(38133, 'koKR', 'Powstań i raduj się swoją czystą postacią!', '', 0),
(38134, 'koKR', 'Spójrzcie na swoje prymitywne dłonie: ścięgna, miękkie mięso, ciemną krew, która w nich krąży.', '', 0),
(38135, 'koKR', 'To słabość, wyniszczająca skaza... Żart, jaki Stwórcy spłatali własnym stworzeniom.', '', 0),
(38136, 'koKR', 'Im prędzej uznacie swój stan za wadę, tym prędzej będziecie w stanie go przekroczyć.', '', 0),
(38137, 'koKR', 'Dzięki naszemu Panu wszystko jest możliwe. Jego moc nie zna granic, a jego wola jest niezłomna.', '', 0),
(38138, 'koKR', 'Ci, którzy mu się sprzeciwiają, zostaną doszczętnie zniszczeni, a ci, którzy mu służą – służą całkowicie, bez pytań, z bezgranicznym oddaniem umysłu i duszy – zostaną wyniesieni na wyżyny, o jakich wam się nie śniło.', '', 0),
(38139, 'koKR', 'Trafiliście tutaj, bo należycie do nielicznych obdarzonych prawdziwym wzrokiem w świecie przeklętym ślepotą.', '', 0),
(38140, 'koKR', 'Widzicie przez mgłę, która wisi nad tym światem niczym całun, i pojmujecie, gdzie leży prawdziwa moc.', '', 0),
(38143, 'koKR', 'Ojcze...', '', 0),
(38150, 'koKR', 'Ojcze. Obawiałem się o twój... twój rozum.', '', 0),
(38151, 'koKR', 'Ojcze... Za ciebie oddałbym życie tysiąc razy.', '', 0),
(38207, 'koKR', 'Znowu ty... Mam nadzieję, że nie $gliczyłeś:liczyłaś; za bardzo na to, że twoje czyny ukoją mojego ducha. Teraz już wiem, że bez niej nie zaznam spokoju, już nie.$B$BChcę zobaczyć ich domy zrównane z ziemią. Czy jesteś $ggotów:gotowa; zabić więcej tych obrzydliwych morderców?', '', 0),
(38224, 'koKR', 'Byłem kiedyś paladynem, $n. Teraz Światłość się ode mnie odwraca, bo moje grzechy są zbyt wielkie.$B$BBędę wspierać sojuszników, jak tylko zdołam, ale już nigdy nie sięgnę po moce ciemności.', '', 0),
(38225, 'koKR', 'To rana zadana własną ręką, $gprzyjacielu:przyjaciółko;. Nie mogłem znieść widoku świata, w którym w szponach Króla Lisza dopuściłem się tylu okropności.$B$BTo był mój pierwszy krok ku odkupieniu, a jeśli moje grzechy są niewybaczalne, będę próbował je odpokutować do końca życia.', '', 0),
(38226, 'koKR', 'Ormusie, co się stało z twoimi oczami?', 'Ormusie, co się stało z twoimi oczami?', 0),
(38227, 'koKR', 'Chyba $gzgubiłem:zgubiłam; pierścień.', 'Chyba $gzgubiłem:zgubiłam; pierścień.', 0),
(38229, 'koKR', 'Tak się nie stanie.', 'Tak się nie stanie.', 0),
(38363, 'koKR', '%s zaczyna rzucać Rozprysk szlamu!', '', 0),
(38385, 'koKR', '', 'Po niezliczonych nieudanych próbach zdobycia przez naszych agentów użytecznych próbek zarazy Plagi do analizy osobiście nadzoruję teraz prace na pierwszej linii frontu. Jak to mówią: jeśli chcesz, żeby coś było zrobione porządnie...', 0),
(38464, 'koKR', 'MOCĄ KRÓLA LISZA!', '', 0),
(38466, 'koKR', 'Ucztujcie, moje sługi!', '', 0),
(38498, 'koKR', '%s rzuca |cFFFF7F00Duszącą bombę gazową!|r', '', 0),
(38499, 'koKR', '|TInterface\\Icons\\inv_misc_herb_evergreenmoss.blp:16|t%s rzuca |cFF00FF00Plastyczną maź!|r', '', 0),
(38500, 'koKR', '%s zaczyna rzucać Niestabilny eksperyment!', '', 0),
(38515, 'koKR', 'Pragniesz krwi!', 'Pragniesz krwi!', 0),
(38517, 'koKR', 'Ja... budzę się!', '', 0),
(38518, 'koKR', 'Kto... tam...?', '', 0),
(38545, 'koKR', 'Tego się nie spodziewałem!', '', 0),
(38546, 'koKR', 'Wspaniałe wieści, moi drodzy!', '', 0),
(38562, 'koKR', 'Wy... nie uciekniecie nam!', 'Wy... nie uciekniecie nam!', 0),
(38563, 'koKR', 'Szybko! Zaatakujemy ich od tyłu!', 'Szybko! Zaatakujemy ich od tyłu!', 0),
(38564, 'koKR', 'Żywi... tutaj?!', 'Żywi... tutaj?!', 0),
(38588, 'koKR', 'Inwokacja krwi przeskakuje na księcia Kelesetha!', '', 0),
(38589, 'koKR', 'Inwokacja krwi przeskakuje na księcia Valanara!', '', 0),
(38590, 'koKR', 'Inwokacja krwi przeskakuje na księcia Taldarama!', '', 0),
(38619, 'koKR', 'Cienie gromadzą się i kłębią wokół celu: $n!', 'Cienie gromadzą się i kłębią wokół celu: $n!', 0),
(38624, 'koKR', 'Wzmocnione płomienie mkną ku celowi: $n!', '', 0),
(38631, 'koKR', '%s: krwawe bestie wyczuwają zapach krwi!', '', 0),
(38679, 'koKR', '$n zostaje $gzarażony:zarażona; Zarazą śmierci!', '', 0),
(38682, 'koKR', 'Intruzi wdarli się do wewnętrznego sanktuarium. Przyspieszcie zniszczenie zielonego smoka! Zostawcie tylko kości i ścięgna do reanimacji!', '', 0),
(38796, 'koKR', 'Pokaż mi zbroje władców Plagi, Ormusie.', 'Pokaż mi zbroje władców Plagi, Ormusie.', 0),
(38806, 'koKR', 'Witaj, $gbohaterze:bohaterko;. Wytwarzam i sprzedaję zbroje z tkaniny smagaczy Frei dla druidów.', 'Witaj, $gbohaterze:bohaterko;. Wytwarzam i sprzedaję zbroje z tkaniny smagaczy Frei dla druidów.', 0),
(38809, 'koKR', 'Witaj, $gbohaterze:bohaterko;. Wytwarzam i sprzedaję zbroje mroźnej wiedźmy dla szamanów.\n', 'Witaj, $gbohaterze:bohaterko;. Wytwarzam i sprzedaję zbroje mroźnej wiedźmy dla szamanów.\n', 0),
(38810, 'koKR', 'Witaj, $gbohaterze:bohaterko;. Wytwarzam i sprzedaję zbroje cienistego ostrza dla łotrzyków.\n', 'Witaj, $gbohaterze:bohaterko;. Wytwarzam i sprzedaję zbroje cienistego ostrza dla łotrzyków.\n', 0),
(38811, 'koKR', 'Witaj, $gbohaterze:bohaterko;. Wytwarzam i sprzedaję zbroje krwawego łowcy Ahn\'Kahar dla łowców.', 'Witaj, $gbohaterze:bohaterko;. Wytwarzam i sprzedaję zbroje krwawego łowcy Ahn\'Kahar dla łowców.', 0),
(38812, 'koKR', 'Witaj, $gbohaterze:bohaterko;. Wytwarzam i sprzedaję zbroje władcy Ymirjarów dla wojowników.', '', 0),
(38813, 'koKR', 'Witaj, $gbohaterze:bohaterko;. Wytwarzam i sprzedaję zbroje zaprzysiężonego Światłości dla paladynów.\n', 'Witaj, $gbohaterze:bohaterko;. Wytwarzam i sprzedaję zbroje zaprzysiężonego Światłości dla paladynów.\n', 0),
(38814, 'koKR', 'Witaj, $gbohaterze:bohaterko;. Wytwarzam i sprzedaję zbroje karmazynowego akolity dla kapłanów.\n', 'Witaj, $gbohaterze:bohaterko;. Wytwarzam i sprzedaję zbroje karmazynowego akolity dla kapłanów.\n', 0),
(38815, 'koKR', 'Witaj, $gbohaterze:bohaterko;. Wytwarzam i sprzedaję zbroje maga krwi dla magów.\n', 'Witaj, $gbohaterze:bohaterko;. Wytwarzam i sprzedaję zbroje maga krwi dla magów.\n', 0),
(38816, 'koKR', 'Witaj, $gbohaterze:bohaterko;. Wytwarzam i sprzedaję zbroje mrocznego sabatu dla czarnoksiężników.\n', 'Witaj, $gbohaterze:bohaterko;. Wytwarzam i sprzedaję zbroje mrocznego sabatu dla czarnoksiężników.\n', 0),
(38972, 'koKR', '%s zaczyna rzucać Wzmocniony wir wstrząsu!', '', 0),
(39003, 'koKR', 'Oto stoję, lew przed jagniętami... a one się nie boją.', '', 0),
(39004, 'koKR', 'Nie potrafią się bać...', '', 0),
(39415, 'koKR', 'Słowo się rzekło. Król Lisz zginie z naszych rąk!', 'Słowo się rzekło. Król Lisz zginie z naszych rąk!', 0),
(39416, 'koKR', 'Północna Grań potrzebuje twojej uwagi, nadrządco Piekłoryczu. Poradzimy sobie z Królem Liszem i jego sługami bez twojej pomocy.', 'Północna Grań potrzebuje twojej uwagi, nadrządco Piekłoryczu. Poradzimy sobie z Królem Liszem i jego sługami bez twojej pomocy.', 0),
(39417, 'koKR', 'Z Ofensywą Wojennej Pieśni tutaj, w Cytadeli Lodowej Korony, zwycięstwo jest w naszym zasięgu! Śmierć Króla Lisza przyniesie Hordzie chwałę!', '', 0),
(39418, 'koKR', 'Odrzucasz potęgę Ofensywy Wojennej Pieśni? Czy chaos bitwy odebrał ci rozum? Z moją pomocą zwycięstwo jest blisko! Bez niej czeka was ciężka walka.', '', 0),
(39419, 'koKR', 'Chwała Hordzie!', '', 0),
(39423, 'koKR', 'Twój wybór był śmiały! Szanuję twoje pragnienie chwały i honoru! Zgiń godnie, $n!', '', 0),
(39688, 'koKR', '%s zaczyna rzucać Zbezczeszczenie!', '', 0),
